mapper.select:
select * from (
    select

        (IFNULL(MID_PLAN_QTY, 0) + IFNULL(NIGHT_PLAN_QTY, 0) + IFNULL(DAY_PLAN_QTY, 0)) as daily_total_qty,
        b.MONTH_PLAN_QTY as month_plan,
        b.MONTH_REMAIN_QTY as month_plan_os,
        d.DIMENSION,
        e.COLOR_TYPE,
        e.COLOR_CODE
    from t_gsq_assist_schedule a
    LEFT JOIN (
        select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY from T_GSQ_MONTH_PLAN_SURPLUS
        where YEAR=#{year,jdbcType=VARCHAR}
        and MONTH= #{month,jdbcType=VARCHAR}
        and del_flag = '0'
    ) b on a.STEEL_RING_CODE=b.MATERIAL_CODE
    LEFT JOIN T_GSQ_STEEL_TYPE_COLOR e ON a.STEEL_TYPE = e.STEEL_TYPE AND e.STATUS = '0' AND e.DEL_FLAG = '0'
    LEFT JOIN (
        SELECT BEAD_CODE, max(DIMENSION) DIMENSION FROM T_PRODUCT_CONSTRUCTION_INFO
        group by BEAD_CODE
    ) d on a.STEEL_RING_CODE = d.BEAD_CODE
    where a.del_flag = '0'
    and a.schedule_date = #{scheduleDate}
    and INSTR(a.steel_type, #{steelType}) > 0

        and INSTR(a.steel_ring_code, #{steelRingCode,jdbcType=VARCHAR}) > 0

    and a.production_status = #{productionStatus}

        and instr(concat(',',a.machine_id,','),  concat(',',#{machineId},','))>0

    and a.IS_RELEASE = #{isRelease}
    order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,a.RANK, d.DIMENSION
) t

    order by ${orderStr}
